#!/usr/bin/env bash
#
# Cấu hình đăng nhập Google cho dgai.
# Generated by the /wizard skill.
#
# Google chỉ cấp OAuth client qua Google Cloud Console, nên phần tạo client là
# việc con người làm; wizard này dẫn từng bước rồi tự ghi cấu hình vào dgai qua
# API quản trị.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

TOTAL_STAGES=0

_STAGE_INDEX=0
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

ask() {
  local key="$1" prompt="$2" input rc=0
  printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  read -e -r input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" input rc=0
  printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  printf -v "$key" '%s' "$input"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

# api METHOD PATH [JSON] — gọi API dgai bằng token quản trị đã đăng nhập.
api() {
  local method="$1" path="$2" body="${3:-}"
  if [[ -n "$body" ]]; then
    curl -sS -X "$method" "$SITE$path" \
      -H "Authorization: Bearer $ADMIN_TOKEN" -H 'Content-Type: application/json' \
      --data-binary "$body"
  else
    curl -sS -X "$method" "$SITE$path" -H "Authorization: Bearer $ADMIN_TOKEN"
  fi
}

json_escape() {
  local s="$1"
  s="${s//\\/\\\\}"; s="${s//\"/\\\"}"
  printf '%s' "$s"
}

run_wizard() {

TOTAL_STAGES=6

banner "Đăng nhập Google cho dgai"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Địa chỉ dgai"
say "Redirect URI Google cần khớp chính xác host của bạn, nên chốt trước."
ask SITE "Địa chỉ dgai (mặc định https://dgai.io.vn):"
SITE="${SITE:-https://dgai.io.vn}"
SITE="${SITE%/}"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Google Cloud: tạo / chọn project"
say "Google cấp OAuth client trong Google Cloud Console. Nếu đã có project dùng"
say "cho dgai thì chọn lại, chưa có thì tạo mới (miễn phí, không cần thẻ)."
open_url "https://console.cloud.google.com/projectcreate"
step "Đặt tên project, ví dụ 'dgai', rồi bấm Create."
step "Xong thì mở trang chọn project bên dưới và chọn đúng project đó."
open_url "https://console.cloud.google.com/projectselector2/home/dashboard"
pause "Enter khi đã ở đúng project."

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "OAuth consent screen"
say "Màn hình đồng ý là trang Google hiện cho người dùng khi họ đăng nhập."
say "Chọn External; ứng dụng có thể để Testing — chỉ tài khoản trong danh sách"
say "Test users đăng nhập được, đủ cho giai đoạn tạm thời."
open_url "https://console.cloud.google.com/apis/credentials/consent"
step "Chọn External → Create."
step "App name: dgai · User support email: email của bạn."
step "Developer contact: email của bạn → Save and Continue."
step "Bỏ qua Scopes → Save and Continue."
step "Ở Test users: Add users → thêm địa chỉ Gmail được phép đăng nhập."
pause "Enter khi consent screen đã lưu."

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Tạo OAuth client (Web application)"
say "Redirect URI phải khớp CHÍNH XÁC chuỗi dưới đây, nếu lệch một ký tự Google"
say "sẽ trả redirect_uri_mismatch:"
say ""
printf '    %s%s/oauth/google%s\n' "$BOLD" "${SITE:-https://dgai.io.vn}" "$RESET"
say ""
open_url "https://console.cloud.google.com/apis/credentials"
step "Create credentials → OAuth client ID."
step "Application type: Web application · Name: dgai web."
step "Authorized redirect URIs → Add URI → dán đúng chuỗi ở trên."
step "Create → cửa sổ hiện Client ID và Client secret."
pause "Enter khi cửa sổ credentials đang mở."

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Nhập credentials"
ask CLIENT_ID "Paste Client ID (kết thúc bằng .apps.googleusercontent.com):"
ask_secret CLIENT_SECRET "Paste Client secret (bắt đầu bằng GOCSPX-):"
note "Credentials chỉ được gửi tới dgai của bạn, không lưu ra file."

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Ghi cấu hình vào dgai"
say "Ghi provider vào $SITE"
ask ADMIN_USER "Tài khoản quản trị (mặc định admin):"
ADMIN_USER="${ADMIN_USER:-admin}"
ask_secret ADMIN_PASSWORD "Mật khẩu quản trị:"

login_body=$(printf '{"username":"%s","password":"%s"}' \
  "$(json_escape "$ADMIN_USER")" "$(json_escape "$ADMIN_PASSWORD")")
login_resp=$(curl -sS -X POST "$SITE/api/user/login" \
  -H 'Content-Type: application/json' --data-binary "$login_body")
ADMIN_TOKEN=$(printf '%s' "$login_resp" | sed -n 's/.*"access_token":"\([^"]*\)".*/\1/p')
if [[ -z "$ADMIN_TOKEN" ]]; then
  warn "Đăng nhập thất bại: $login_resp"
  exit 1
fi
say "Đã đăng nhập quản trị."

redirect="$SITE/oauth/google"
provider_body=$(cat <<JSON
{
  "name": "Google",
  "slug": "google",
  "enabled": true,
  "client_id": "$(json_escape "$CLIENT_ID")",
  "client_secret": "$(json_escape "$CLIENT_SECRET")",
  "authorization_endpoint": "https://accounts.google.com/o/oauth2/v2/auth",
  "token_endpoint": "https://oauth2.googleapis.com/token",
  "user_info_endpoint": "https://openidconnect.googleapis.com/v1/userinfo",
  "scopes": "openid email profile",
  "user_id_field": "sub",
  "username_field": "email",
  "display_name_field": "name",
  "email_field": "email",
  "auth_style": 1
}
JSON
)

existing=$(api GET /api/custom-oauth-provider/)
provider_id=$(printf '%s' "$existing" | tr '}' '\n' | grep '"slug":"google"' | sed -n 's/.*"id":\([0-9]*\).*/\1/p' | head -n1)
if [[ -n "$provider_id" ]]; then
  say "Đã có provider google (id $provider_id) — cập nhật credentials."
  resp=$(api PUT "/api/custom-oauth-provider/$provider_id" "$provider_body")
else
  say "Tạo provider google."
  resp=$(api POST /api/custom-oauth-provider/ "$provider_body")
fi

if printf '%s' "$resp" | grep -q '"success":true'; then
  printf '  %s✓ wrote%s provider google → dgai\n' "$GREEN" "$RESET"
else
  warn "Ghi cấu hình thất bại: $resp"
  exit 1
fi

status=$(curl -sS "$SITE/api/status")
if printf '%s' "$status" | grep -q '"slug":"google"'; then
  printf '  %s✓ ok%s /api/status đã trả provider google\n' "$GREEN" "$RESET"
else
  warn "Provider chưa xuất hiện trong /api/status — kiểm tra lại."
fi

say ""
say "Kiểm tra cuối: mở trang đăng nhập, nút 'Continue with Google' phải hiện."
open_url "$SITE/sign-in"

finish
}

run_wizard "$@"; exit
